// Validate and prepare scraper request
const body = $input.first().json.body;

const validSources = ['apex-jobs', 'insight-global-jobs', 'teksystems-jobs', 'all'];
const source = body.source || 'apex-jobs';

if (!validSources.includes(source)) {
  throw new Error(`Invalid source: ${source}. Valid sources: ${validSources.join(', ')}`);
}

return {
  json: {
    source: source,
    locations: body.locations || ['Washington DC', 'Virginia', 'Maryland'],
    max_items: Math.min(body.max_items || 100, 500),
    sync_to_hub: body.sync_to_hub !== false
  }
};

// Process scraper response
const response = $input.first().json;
const request = $('Validate Request').first().json;

return {
  json: {
    success: response.status === 'completed' || response.status === 'success',
    source: request.source,
    jobs_scraped: response.jobs_scraped || response.count || 0,
    jobs_synced: response.synced || 0,
    duration_seconds: response.duration_seconds || 0,
    message: response.message || `Scraping ${request.source} completed`,
    details: response,
    timestamp: new Date().toISOString()
  }
};
